const item = $input.first() || { json: {} };
const headers = item.json.headers || {};
const body = item.json.body || item.json || {};

// Determine trigger type: explicit body.trigger, or default to manual
const triggerType = body.trigger || 'manual';

if (triggerType === 'geofence') {
  const expectedSecret = $env.GEOFENCE_WEBHOOK_SECRET || '';
  const providedSecret = headers['x-webhook-secret'] || body.secret || '';
  if (expectedSecret && providedSecret !== expectedSecret) {
    throw new Error('Invalid webhook secret. Rejecting request.');
  }
}

return [{ json: { triggerType, timestamp: new Date().toISOString() } }];

const items = $input.all();
const results = [];
for (const item of items) {
  const friends = item.json.friends_identified || [];
  const friendCount = friends.length;
  const isVideo = item.json.is_video;
  if (friendCount >= 2) {
    results.push({ json: { ...item.json, _routing: { type: 'group', recipientJid: $env.WHATSAPP_GROUP_JID, recipientName: 'Squad Group', sendAs: isVideo ? 'media' : 'document', friends: friends, caption: isVideo ? '' : ('PIC ' + friends.join(' & ')) } } });
  } else if (friendCount === 1) {
    results.push({ json: { ...item.json, _routing: { type: 'dm', friendName: friends[0], sendAs: isVideo ? 'media' : 'document', friends: friends, caption: '' } } });
  }
}
return results;

const items = $input.all();
const results = [];
for (const item of items) {
  const routing = item.json._routing;
  if (routing.type === 'group') {
    results.push({ json: item.json });
  } else {
    results.push({ json: { ...item.json, _contactLookupNeeded: true, _friendToLookup: routing.friendName ? routing.friendName.replace(/'/g, "''") : null } });
  }
}
return results;

// ============================================================
// Merge Contact Info & Build Send Payload
// ============================================================
// Inputs arrive on a single slot from two branches:
//   * GROUP items  -> still carry `_routing` (straight from "Is DM?" false)
//   * DM rows      -> raw Postgres rows (subject_name, whatsapp_jid,
//                     display_name, send_preference). NO `_routing`.
//
// The Postgres node drops n8n pairedItem metadata, so itemMatching() is
// unreliable (it can silently return the wrong row). We re-pair each DB row
// to the next UNUSED original DM media item by the friend's raw name, so the
// same friend appearing in several separate photos is paired correctly.
// ============================================================

const items = $input.all();

// Original DM media items, in order, still un-consumed.
const dmOriginals = $('Prepare Contact Lookup')
  .all()
  .filter(o => o.json && o.json._contactLookupNeeded === true);
const usedOriginal = new Set();

const results = [];

for (const item of items) {
  const data = item.json;
  let original;
  let contact = null;

  if (data._routing) {
    // GROUP item: already complete.
    original = data;
  } else {
    // DM contact row from Postgres -> re-pair to its media item by raw name.
    contact = data;
    const dbSubject = contact.subject_name;
    const matchIdx = dmOriginals.findIndex(
      (o, i) => !usedOriginal.has(i)
        && o.json._routing
        && o.json._routing.friendName === dbSubject
    );
    if (matchIdx === -1) {
      throw new Error('Could not match DB contact back to a media file. Subject: ' + dbSubject);
    }
    usedOriginal.add(matchIdx);
    original = dmOriginals[matchIdx].json;
  }

  const routing = original._routing;
  let recipientJid, recipientName;

  if (routing.type === 'group') {
    recipientJid = routing.recipientJid;
    recipientName = routing.recipientName;
  } else {
    recipientJid = contact.whatsapp_jid;
    recipientName = contact.display_name || routing.friendName;

    if (!recipientJid) {
      throw new Error('No WhatsApp JID found for friend: ' + routing.friendName + '. Add them to friends_contacts.');
    }

    if (contact.send_preference === 'group_only') {
      results.push({
        json: {
          mediaId: original.media_id !== undefined ? original.media_id : null,
          _skip: true,
          _skipReason: 'Friend prefers group_only'
        }
      });
      continue;
    }
  }

  results.push({
    json: {
      mediaId: original.media_id !== undefined ? original.media_id : null,
      sessionId: original.session_id !== undefined ? original.session_id : null,
      localPath: original.local_path || '',
      originalFilename: original.original_filename || '',
      isVideo: original.is_video !== undefined ? original.is_video : false,
      recipientJid: recipientJid || null,
      recipientName: recipientName || null,
      recipientType: routing.type || null,
      sendAs: routing.sendAs || null,
      caption: routing.caption || '',
      friends: routing.friends || []
    }
  });
}

return results;

// ============================================================
// Human-like Delay + Batch Cooldown (Ban Prevention)
// ============================================================
// Runs once PER message so the static batch counter advances per send and
// each send gets its own randomized delay; every BATCH_SIZE sends triggers a
// longer cooldown.
//
// NOTE: n8n finishes this node for all items before "Send via WhatsApp" runs,
// so this paces overall throughput / triggers cooldowns but does NOT interleave
// the individual HTTP sends. For strict inter-send spacing, wrap this node and
// "Send via WhatsApp" in a "Loop Over Items" (batch size 1) and feed the loop's
// output back into this node.
// ============================================================

const minDelay = parseInt($env.WA_MIN_DELAY_MS) || 4000;
const maxDelay = parseInt($env.WA_MAX_DELAY_MS) || 12000;
const batchSize = parseInt($env.WA_BATCH_SIZE) || 8;
const batchCooldown = parseInt($env.WA_BATCH_COOLDOWN_MS) || 180000;

const staticData = $getWorkflowStaticData('global');
staticData._batchCount = (staticData._batchCount || 0) + 1;

if (staticData._batchCount > 1 && (staticData._batchCount - 1) % batchSize === 0) {
  await new Promise(resolve => setTimeout(resolve, batchCooldown));
} else {
  const delay = Math.floor(Math.random() * (maxDelay - minDelay)) + minDelay;
  await new Promise(resolve => setTimeout(resolve, delay));
}

return $input.item;

// Encode media to base64 and re-attach delivery metadata.
// 'Read Media File' outputs binary only and drops the item JSON, and
// $binary.data.data is NOT exposed as base64 in expressions on this n8n
// build. We pull the buffer via the helper and merge back the metadata from
// 'Rate Limit Delay' (1:1 item order is preserved through the file read).
const items = $input.all();
const meta = $('Rate Limit Delay').all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  out.push({
    json: { ...meta[i].json, mediaBase64: buffer.toString('base64') },
    pairedItem: { item: i }
  });
}
return out;

const items = $('Build Send Payload').all();
const sentItems = items.filter(i => !i.json._skip);
const summary = { totalSent: sentItems.length, groupMessages: sentItems.filter(i => i.json.recipientType === 'group').length, dmMessages: sentItems.filter(i => i.json.recipientType === 'dm').length, friends: [...new Set(sentItems.flatMap(i => i.json.friends || []))], timestamp: new Date().toISOString() };
const summaryText = 'AutoSharePics Summary

Sent: ' + summary.totalSent + '
Group: ' + summary.groupMessages + '
DMs: ' + summary.dmMessages + '
Friends: ' + summary.friends.join(', ');
return [{ json: { summaryText, ...summary } }];
